lib.script:
			var gLogNote = "LOG";
var gCurrentLang = "DE";
var gLanguages = "DE,EN";
var gTranslInforegexp =/TRANSLATION\{[^}]*\}/;
var logInitialized = false;

function initLog(){
	if (! logInitialized){
		var lNote = model.getNoteSet().getByName(gLogNote);
     	if (lNote == null) {
    	    		lNote = model.createNote()
	    		lNote.setName(gLogNote);
     	}
     	lNote.setComment("");
     	logInitialized = true;
	}
}
function log(plog){
	initLog();
	var lNote = model.getNoteSet().getByName(gLogNote);
     lNote.setComment(lNote.getComment()+"\n"+plog);
}

function getTranslInfo(){
	var lDesignComment = model.design.getComment();
     lmatchTransl= lDesignComment.match(gTranslInforegexp);
     return lmatchTransl;    
}

function setTranslInfo(curLang,langs) {
	model.design.setComment(
		"TRANSLATION{\ncurrentLang="
		+curLang+"\nlanguages="
		+langs+"\nlastSync=\n}\n"
		+ model.design.getComment());
}
function updTranslInfo(curLang,langs,datetime) {
	curComment = model.design.getComment();
	model.design.setComment(
		curComment.replace(gTranslInforegexp,
		"TRANSLATION{\ncurrentLang="
		+curLang+"\nlanguages="
		+langs+"\nlastSync="+datetime+"\n}"
		));
}

function init(){
	lmatchTransl = getTranslInfo();
	if (lmatchTransl == null) {
		throw new Error("***TRANSLATION not initstalled***");
	}
	ltext= String(lmatchTransl).match(/currentLang=[A-Z]{2}/);
	lparts = String(ltext).split("=");
	//log("curLang="+lparts[1]);
     gCurrentLang = lparts[1];

	ltext= String(lmatchTransl).match(/languages=[A-Z,]*/);
	lparts = String(ltext).split("=");
     //log("languages="+lparts[1]);
     gLanguages = lparts[1]
}

function doProperty(lang,propName,obj,value){
	lpropName = lang + propName;
	if (lang == gCurrentLang) {
		// die Werte sind ok überschreibe immer
		obj.setProperty(lpropName
		       ,value)
	} else {
		ldest = obj.getProperty(lpropName);
		//log("ldest="+ldest+" value="+value);
		// schreibe nur, wenn Ziel leer ist.
		if (ldest == '')  {
		//   log("2ldest="+ldest+" value="+value);		  
		 	// bei leerem Wert setze keinen Prefix
			lprefix = (value == '') ? '' 
				: '*'+gCurrentLang+'* '
			obj.setProperty(lpropName	
	   	            ,lprefix+value)
		}

	}
}

function fuellUDP(lang){
	entities = model.getEntitySet().toArray();
//	ent = entities.getByName('Agent');
//	log("Entitäten="+entities.length);
	for (i=0;i<entities.length;i++) { //
		ent = entities[i];
		doProperty(lang,"_ENT_NAME",ent,ent.getName())
		doProperty(lang,"_ENT_COMMENT",ent,ent.getComment())
		doProperty(lang,"_ENT_SYNONYM",ent,ent.getSynonym())
		if (ent.getProperty("DE" + "_ENT_NAME") == ''){
			// noch nicht initialisiert
			doProperty("DE","_ENT_NAME",ent,ent.getName())
			doProperty("DE","_ENT_COMMENT",ent,ent.getComment())
			doProperty("DE","_ENT_SYNONYM",ent,ent.getSynonym())
		}
		if (ent.getProperty("EN" + "_ENT_NAME") == ''){
			// noch nicht initialisiert
			doProperty("EN","_ENT_NAME",ent,ent.getName())
			doProperty("EN","_ENT_COMMENT",ent,ent.getComment())
			doProperty("EN","_ENT_SYNONYM",ent,ent.getSynonym())
		}

		attrs = ent.getAttributes().toArray();
		//log("Attrs="+attrs.length)
		for (j=0;j<attrs.length;j++) { //
			attr = attrs[j];
			//log(attr.getName(),attr.getComment());
			doProperty(lang,"_ATTR_NAME",attr,attr.getName());
			doProperty(lang,"_ATTR_COMMENT",attr,attr.getComment());			
			if (ent.getProperty("DE" + "_ATTR_NAME") == ''){
				doProperty("DE","_ATTR_NAME",attr,attr.getName());
				doProperty("DE","_ATTR_COMMENT",attr,attr.getComment());			
			}	
			if (ent.getProperty("EN" + "_ATTR_NAME") == ''){
				doProperty("EN","_ATTR_NAME",attr,attr.getName());
				doProperty("EN","_ATTR_COMMENT",attr,attr.getComment());			
			}	
		}
		ent.setDirty(true);
	}
	relationships = model.getRelationSet().toArray();
	for (r=0;r<relationships.length;r++) { //
		rel = relationships[r];
		doProperty(lang,"_TEXT_FROM",rel,rel.getNameOnSource())
		doProperty(lang,"_TEXT_TO",rel,rel.getNameOnTarget())
		rel.setDirty(true);
	}
}

function liesUDP(lang){
	entities = model.getEntitySet().toArray();
	for (i=0;i<entities.length;i++) { //
		ent = entities[i];
		ent.setName(ent.getProperty(lang+"_ENT_NAME"));
		ent.setComment(ent.getProperty(lang+"_ENT_COMMENT"));
		ent.setSynonym(ent.getProperty(lang+"_ENT_SYNONYM"));

		attrs = ent.getAttributes().toArray();
		//log("Attrs="+attrs.length)
		for (j=0;j<attrs.length;j++) { //
			attr = attrs[j];
			//log(attr.getName(),attr.getComment());
			attr.setName(attr.getProperty(lang+"_ATTR_NAME"));
			attr.setComment(attr.getProperty(lang+"_ATTR_COMMENT"));			
		}		
		ent.setDirty(true);
	}
	relationships = model.getRelationSet().toArray();
	for (r=0;r<relationships.length;r++) { 
		rel = relationships[r];
		if (rel.getName()=='Relation_42'){
		//	log(lang+"textfrom="+rel.getProperty(lang+"_REL_TEXT_FROM"));
			rel.setComment("from="+rel.getProperty(lang+"_TEXT_FROM")
			+"\nto="+rel.getProperty(lang+"_TEXT_TO"))
		}
		rel.setNameOnSource(rel.getProperty(lang+"_TEXT_FROM"));
		rel.setNameOnTarget(rel.getProperty(lang+"_TEXT_TO"));
		rel.setDirty(true);
	}
}

function curDateStr(){
	var currentdate = new Date();
	return  currentdate.getDate() 
	+ "/" + (currentdate.getMonth()+1) 
	+ "/" + currentdate.getFullYear() + "  " 
	+ currentdate.getHours() + ":" 
	+ currentdate.getMinutes() + ":" + currentdate.getSeconds();
}
function initTranslation() {
	lmatchTransl= getTranslInfo()
	if (lmatchTransl == null) {
		setTranslInfo(gCurrentLang
		,gLanguages);		
	} 
	//hier gibt es einen Eintrag für die Translation
	init();
	// fülle die UDP für die Übersetzungen
	fuellUDP('DE');
	fuellUDP('EN');
	updTranslInfo(gCurrentLang, gLanguages
				,curDateStr());
	model.design.setDirty(true);
}


function changeLang(pfromLang,ptoLang){
	//log("3:"+gLanguages);
//	log("change from " + pfromLang + " to " + ptoLang);
	fuellUDP(pfromLang);
	liesUDP(ptoLang);
	gCurrentLang = ptoLang;
	updTranslInfo(gCurrentLang, gLanguages
				,curDateStr());	
}

function change2DE() {
	init();
	changeLang(gCurrentLang,'DE');
}

function change2EN() {
	init();
	changeLang(gCurrentLang,'EN');
}
